package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; an OPEN claim a clerk settles above
 *  the clerk limit is PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
 *  DRAFT, OPEN or PENDING claim can be VOID, and a steward may void a SETTLED one within 7 days of
 *  its settlement. A DRAFT can be DELETED, counting nowhere, and restored to a DRAFT on the sheet's
 *  today it was deleted. A claim whose due is above the review threshold goes to REVIEW when opened,
 *  counting nowhere until a steward reviews it (OPEN); a REVIEW claim can be VOID. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether the claim counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is open: OPEN, or PENDING an approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may be moved to another person: a SETTLED or VOID one cannot. */
    public boolean canReassign() {
        return this == DRAFT || this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may be opened, settled or voided to the given one; a PENDING
     *  claim leaves PENDING only by being approved, rejected or voided. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == REVIEW;
            case PENDING, DRAFT, DELETED, REVIEW -> false;
        };
    }
}
    public void addProof(String kind) {
        this.proofs++;
        if (ProofKind.PHOTO.equals(kind)) {
            this.proofsPhoto++;
        } else {
            this.proofsReceipt++;
        }
    }

    /** Whether the claim is deferred on a day: that day is before its deferred-until date and no
     *  statement binds it. A deferral takes effect only once the binding ends, so a claim settled while
     *  bound is deferred too once unbound. From that date on it is a claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return (status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED) && !stated && deferredUntil != null
                && today.isBefore(deferredUntil);
    }

    /** Whether the claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED ones do. */
    public boolean counts() {
        return status.counts();
    }

    /** Whether the claim is left out for its person's retirement: it is OPEN or PENDING and the
     *  sheet's today is on or after the date they are retired from (null: not retired). */
    public boolean retiredOn(LocalDate retiredFrom, LocalDate today) {
        return status.isOpen() && retiredFrom != null && !today.isBefore(retiredFrom);
    }

    /** Whether the claim counts in live totals on the sheet's today given its person's retirement date:
     *  one that counts and is not deferred, unless it is OPEN or PENDING once its person is retired and
     *  not bound by a statement (a bound claim stays in whatever its date). A hold does not take it out:
     *  a hold only bears on the pools' cuts. */
    public boolean countsLive(LocalDate retiredFrom, LocalDate today) {
        return counts() && !deferredOn(today) && (stated || !retiredOn(retiredFrom, today));
    }

    /** Whether the claim counts in a period's live figures, given the status it had at the end of the
     *  period's last day (null when it was added after): that status counts, and the live rules leave
     *  it in (not deferred on the sheet's today, and not retired out unless bound by a statement). */
    public boolean countsAsOf(ClaimStatus then, LocalDate retiredFrom, LocalDate today) {
        return then != null && then.counts() && !deferredOn(today) && (stated || !retiredOn(retiredFrom, today));
    }
}
